-- Caso confirmado por el propietario; sólo contenido de guía, sin movimientos monetarios.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado)
VALUES ('dos-cargos-mismo-alumno-1000',$texto$Pagar inscripción y mensualidad del mismo alumno: $600 + $400$texto$,'Cobranza',$texto$Liquidar dos adeudos del mismo alumno con un solo pago de $1,000.00, verificando distribución, cuenta bancaria y portal familiar sin pagar otras deudas.$texto$,$texto$Una inscripción vigente con tutor responsable financiero y acceso familiar; cuenta bancaria activa del plantel y moneda correspondientes. Usuario administrativo persistido autorizado para conceptos, cuotas, adeudos, pagos y consulta de cuentas. Caso sin becas, descuentos ni recargos. Si ya completaste la prueba, consulta los resultados y no repitas las cuotas ni el pago. El adeudo anterior de $400.00 de condonación cancelada se mantiene fuera de este caso.$texto$,$texto$Inscripción de prueba $600.00 y mensualidad de prueba $400.00, del mismo alumno: un pago con tarjeta $1,000.00 deja ambos saldos en $0.00 y banco B + $1,000.00. La deuda anterior de $400.00 permanece pendiente. El propietario confirmó ingreso bancario, desaparición de ambos pendientes familiares y conservación de esa deuda anterior el 08/10/2026.$texto$,1,DATE '2026-10-08','CONFIRMADA');
INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo=ANY(ARRAY['CONCEPTO_COBRO_ADMINISTRAR','CUOTA_ALUMNO_ADMINISTRAR','CARGO_ADMINISTRAR','PAGO_LEER','PAGO_REGISTRAR','PAGO_VALIDAR','CUENTA_FINANCIERA_LEER']) WHERE g.slug='dos-cargos-mismo-alumno-1000';
INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.numero,v.titulo,v.perfil,v.modulo,v.instrucciones,v.ejemplo,v.resultado,v.precaucion,v.ruta FROM guia_proceso g JOIN (VALUES
('dos-cargos-mismo-alumno-1000',1,$texto$Crear o reutilizar los dos conceptos de prueba$texto$,$texto$Administración$texto$,$texto$Conceptos de cobro$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Conceptos de cobro. Busca INS-DOBLE-TEST → Aplicar filtros; si ya existe, comprueba que sea de prueba y reutilízalo. 2. Si no existe, pulsa Nuevo registro: selecciona institución, Código INS-DOBLE-TEST, Nombre Inscripción prueba dos cargos y Categoría Inscripción; marca Concepto activo, deja Permite beca, Permite descuento y Permite recargo desmarcados y pulsa Crear concepto. 3. Regresa a Conceptos de cobro, busca MENS-DOBLE-TEST y, sólo si no existe, pulsa Nuevo registro: misma institución, Código MENS-DOBLE-TEST, Nombre Mensualidad prueba dos cargos, Categoría Colegiatura, activo y sin ajustes; pulsa Crear concepto. 4. Busca ambos conceptos en el listado y verifica institución y nombres. No modifiques conceptos de operación real para hacer el ejercicio.$texto$,$texto$INS-DOBLE-TEST para $600.00 y MENS-DOBLE-TEST para $400.00.$texto$,$texto$Dos conceptos activos y separados, sin ajustes.$texto$,$texto$El importe se configura en Cuotas por alumno, no en Conceptos de cobro. No duplicar códigos existentes.$texto$,$texto$/admin/catalogos/conceptos-cobro$texto$),
('dos-cargos-mismo-alumno-1000',2,$texto$Configurar la cuota de inscripción de $600$texto$,$texto$Administración$texto$,$texto$Cuotas por alumno$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Cuotas por alumno → Nuevo registro. Si ya existe la cuota de este ejercicio, consulta y no crees otra. 2. Selecciona institución, plantel, Inscripción vigente del alumno y Concepto de cobro INS-DOBLE-TEST. Captura Importe individual 600.00 y moneda institucional MXN si corresponde. 3. En Calendario y automatización selecciona Una sola vez, Fecha límite de pago 20/10/2026 y Estado Activa; marca Incluir en generación automática de cargos. En Configuración adicional verifica vigencia dentro de inscripción/ciclo, usando las fechas sugeridas. Si octubre no pertenece a la inscripción, adapta el límite y la fecha de generación a un rango válido. 4. Revisa Así quedará la cuota → Crear cuota; comprueba alumno, concepto, importe y fecha en el modal y confirma. Anota la cuota para seleccionarla luego en el generador.$texto$,$texto$Cuota única de inscripción $600.00, vencimiento 20/10/2026.$texto$,$texto$Configuración guardada, todavía sin recibir dinero.$texto$,$texto$Una sola vez no convierte la cuota en mensual. La vigencia adicional es distinta de la fecha límite para pagar.$texto$,$texto$/admin/cuotas-alumno/nuevo$texto$),
('dos-cargos-mismo-alumno-1000',3,$texto$Configurar la mensualidad de prueba de $400$texto$,$texto$Administración$texto$,$texto$Cuotas por alumno$texto$,$texto$1. Desde el menú lateral entra nuevamente a Operación escolar → Cobranza escolar → Cuotas por alumno → Nuevo registro. Reutiliza la cuota si ya existe en este ejercicio. 2. Selecciona exactamente la misma institución, plantel e inscripción del alumno; elige MENS-DOBLE-TEST y captura Importe individual 400.00, moneda institucional. 3. Configura Una sola vez para aislar una mensualidad de prueba, Fecha límite de pago 20/10/2026 y Estado Activa; marca Incluir en generación automática de cargos y verifica vigencia dentro de la inscripción. No uses Cada mes para esta prueba de dos cargos aislados. 4. Revisa el resumen → Crear cuota → modal y confirma. Desde Cuotas por alumno verifica las dos cuotas del mismo alumno por conceptos e importes $600.00 y $400.00.$texto$,$texto$Segundo concepto, misma inscripción; cuota única $400.00.$texto$,$texto$Dos cuotas independientes del mismo alumno.$texto$,$texto$No confundir MENS-DOBLE-TEST con el adeudo anterior de $400.00: el importe coincide, pero son cargos y conceptos diferentes.$texto$,$texto$/admin/cuotas-alumno/nuevo$texto$),
('dos-cargos-mismo-alumno-1000',4,$texto$Generar únicamente los dos adeudos de prueba$texto$,$texto$Administración$texto$,$texto$Adeudos de alumnos → Generar automáticos$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos → Generar automáticos. Selecciona institución y Generar hasta 08/10/2026 si está dentro de la vigencia de ambas cuotas; si adaptaste fechas, utiliza una fecha válida que incluya las dos. 2. Pulsa Visualizar cuotas por aplicar. En Cuotas que generarán adeudos pulsa Desmarcar todos y selecciona sólo INS-DOBLE-TEST por $600.00 y MENS-DOBLE-TEST por $400.00 del mismo alumno. 3. Verifica importes y descuentos cero, total seleccionado $1,000.00; pulsa Confirmar y generar adeudos seleccionados, revisa el modal y confirma una sola vez. No selecciones otras cuotas de prueba. 4. Pulsa Volver a adeudos de alumnos, busca matrícula → Con saldo pendiente → Aplicar filtros. Anota los dos números de cargo por concepto; ambos deben estar sin abonos. Si ya estaban generados, consulta los originales y no dupliques cuotas para volver a generarlos.$texto$,$texto$Dos cargos nuevos $600.00/$400.00, total $1,000.00.$texto$,$texto$Deudas identificadas por número y concepto.$texto$,$texto$La lista de cuotas no incluidas explica exclusiones, no cargos que se vayan a generar. Generar adeudos no registra un pago ni mueve el banco.$texto$,$texto$/admin/cargos/generar$texto$),
('dos-cargos-mismo-alumno-1000',5,$texto$Anotar el saldo bancario antes del pago$texto$,$texto$Administración$texto$,$texto$Cuentas financieras$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Cuentas financieras. Busca la cuenta bancaria del plantel que recibirá el pago y pulsa Aplicar filtros. 2. Anota Saldo actual como B y conserva código/nombre; por ejemplo, si B es $2,000.00, después del pago se espera $3,000.00. No captures estos saldos como movimientos. 3. Confirma cuenta activa y moneda compatible. No selecciones caja para un pago con tarjeta vinculado al banco de este ejercicio. 4. Conserva también los números de los dos cargos del mismo alumno y el número del adeudo anterior de $400.00 que debe quedar fuera del pago.$texto$,$texto$Banco B y dos cargos seleccionables.$texto$,$texto$Referencia para comprobar un único ingreso.$texto$,$texto$Movimientos ajenos durante la prueba deben identificarse aparte; no alterar saldo inicial para que coincida con el ejemplo.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$),
('dos-cargos-mismo-alumno-1000',6,$texto$Registrar un pago único de $1,000 con dos asignaciones$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Nuevo registro$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos → Nuevo registro. En Origen y responsable selecciona institución, plantel y tutor del alumno. 2. En Adeudos que se van a pagar pulsa Agregar cargo, haz clic en Matrícula, alumno o concepto y elige el cargo INS-DOBLE-TEST de $600.00. Pulsa Agregar cargo otra vez y selecciona MENS-DOBLE-TEST de $400.00 de la misma matrícula. No actives Registrar pago parcial ni la alternativa de dinero pendiente de asignar. 3. En Datos del pago confirma Total recibido $1,000.00, Método Tarjeta, Cuenta declarada bancaria anotada y fecha/hora reales. Captura autorización o referencia TEST-DOS-CARGOS-1000 para la prueba; añade observación o comprobante si corresponde. 4. En Revisa y registra comprueba dos tarjetas: $600.00 de este pago y restante $0.00; $400.00 de este pago y restante $0.00. Total recibido/distribuido $1,000.00 y dinero sin asignar $0.00. Pulsa Registrar como pendiente → revisa modal → Confirmar y registrar como pendiente.$texto$,$texto$Un solo pago de $1,000.00, dos cargos diferentes del mismo alumno.$texto$,$texto$Pago guardado pendiente con distribución $600.00/$400.00.$texto$,$texto$No seleccionar el mismo cargo dos veces ni el adeudo anterior de $400.00. Guardar pendiente todavía no modifica la cuenta bancaria.$texto$,$texto$/admin/pagos/nuevo$texto$),
('dos-cargos-mismo-alumno-1000',7,$texto$Validar una sola vez el pago de ambos cargos$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Gestión$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos. Busca TEST-DOS-CARGOS-1000 → Aplicar filtros → Ver; anota folio automático y confirma total $1,000.00. 2. Abre Distribución y comprueba INS-DOBLE-TEST $600.00 y MENS-DOBLE-TEST $400.00, ambos de la misma matrícula, sin asignación al adeudo anterior. 3. Abre Gestión → Control administrativo del pago; conserva la cuenta destino bancaria declarada y pulsa Validar y publicar. Revisa el modal por total y cuenta; Cancelar sólo cierra sin validar. 4. Si coincide, confirma la validación una sola vez y espera Validado. No crees un segundo pago ni registres una entrada manual por cada concepto.$texto$,$texto$Un ingreso bancario $1,000.00 y dos aplicaciones $600.00/$400.00.$texto$,$texto$Dos deudas liquidadas con un único pago.$texto$,$texto$Usar administrador persistido autorizado; no acceso de recuperación. En operación real validar sólo un ingreso comprobado.$texto$,$texto$/admin/catalogos/pagos$texto$),
('dos-cargos-mismo-alumno-1000',8,$texto$Comprobar liquidación y conservación de otra deuda$texto$,$texto$Administración y tutor$texto$,$texto$Cuentas, adeudos, pagos y portal familiar$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Cuentas financieras; busca banco → Aplicar filtros y confirma B + $1,000.00. En Pagos recibidos busca folio → Aplicar filtros → Ver → Distribución; debe existir un solo pago con las dos asignaciones. 2. Entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca matrícula → Liquidado — saldo $0 → Aplicar filtros → Ver de cada cargo de prueba: $600.00 pagados/saldo $0.00 y $400.00 pagados/saldo $0.00. Cambia a Con saldo pendiente para comprobar que el adeudo anterior de $400.00 sigue pendiente y con sus abonos previos intactos. 3. En una ventana privada separada entra a /familias, inicia sesión con el tutor → selecciona el hijo → Tus pagos y recarga. No deben aparecer pendientes INS-DOBLE-TEST ni MENS-DOBLE-TEST; el adeudo anterior de $400.00 sí permanece. En el historial identifica el pago de $1,000.00 y abre su comprobante en otra pestaña; revisa ambos conceptos y total. 4. Para conservar evidencia vuelve a Administración → Finanzas → Pagos recibidos, busca folio y aplica filtros → Exportar Excel. Consulta el comprobante también desde Ver → Comprobantes, sin descargar automáticamente. No repitas el pago al consultar la guía.$texto$,$texto$Banco B + $1,000.00; dos cargos liquidados; la deuda ajena a este pago sigue en $400.00.$texto$,$texto$El propietario confirmó aumento de cuenta, desaparición de ambos pendientes familiares y permanencia de la deuda anterior de $400.00.$texto$,$texto$El portal puede seguir mostrando otras deudas; eso no invalida este pago. Identificar siempre matrícula, concepto y número, no sólo importe.$texto$,$texto$/admin/catalogos/pagos$texto$)
) v(slug,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta) ON g.slug=v.slug;
